import type { CatalogExercise } from "../catalog-exercise";
import { resolveExerciseMedia } from "../media/resolve-exercise-media";
import type { MediaHosting } from "../media/media-hosting";
import type { VocabularyEntry } from "../normalization/vocabulary";

type SqlValue = string | number | null;
type SqlRow = readonly SqlValue[];

export interface CatalogSeedInput {
  exercises: readonly CatalogExercise[];
  muscles: readonly VocabularyEntry[];
  equipment: readonly VocabularyEntry[];
  mediaHosting: MediaHosting;
}

const HEADER = [
  "-- Catalog seed generated by `npm run catalog:seed` from seed-data/catalog/. Do not edit by hand.",
  "-- Idempotent: upserts by slug and rewrites the catalog relation tables. Run with admin credentials.",
].join("\n");

/** Join tables fully owned by the catalog seed; rewritten on every run. */
const RELATION_TABLES = ["exercise_muscles", "exercise_equipment", "exercise_media", "exercise_source_refs"];

export function toSqlLiteral(value: SqlValue): string {
  if (value === null) return "null";
  if (typeof value === "number") return String(value);
  return `'${value.replaceAll("'", "''")}'`;
}

function toValuesList(rows: readonly SqlRow[]): string {
  return rows.map((row) => `  (${row.map(toSqlLiteral).join(", ")})`).join(",\n");
}

function buildUpsert(table: string, columns: readonly string[], rows: readonly SqlRow[]): string {
  const updates = columns.slice(1).map((column) => `${column} = excluded.${column}`).join(", ");
  return `insert into public.${table} (${columns.join(", ")}) values\n${toValuesList(rows)}\non conflict (slug) do update set ${updates};`;
}

interface RelationInsert {
  table: string;
  /** Column names of the inline `values` list, the first one always `exercise_slug`. */
  valueColumns: readonly string[];
  insertColumns: string;
  selectColumns: string;
  extraJoin?: string;
  rows: readonly SqlRow[];
}

/** Inserts relation rows whose foreign keys are looked up by slug. */
function buildRelationInsert(relation: RelationInsert): string {
  if (relation.rows.length === 0) return "";
  return [
    `insert into public.${relation.table} (${relation.insertColumns})`,
    `select ${relation.selectColumns}`,
    `from (values\n${toValuesList(relation.rows)}\n) as v(${relation.valueColumns.join(", ")})`,
    "join public.exercises e on e.slug = v.exercise_slug",
    ...(relation.extraJoin ? [relation.extraJoin] : []),
    "on conflict do nothing;",
  ].join("\n");
}

function buildMuscleRows(exercises: readonly CatalogExercise[]): SqlRow[] {
  return exercises.flatMap((exercise) => [
    ...exercise.primaryMuscles.map((muscle) => [exercise.slug, muscle, "primary"]),
    ...exercise.secondaryMuscles.map((muscle) => [exercise.slug, muscle, "secondary"]),
  ]);
}

function buildMediaRows(exercises: readonly CatalogExercise[], hosting: MediaHosting): SqlRow[] {
  return exercises.flatMap((exercise) =>
    resolveExerciseMedia(exercise.media, hosting).map((media) => [
      exercise.slug, media.mediaType, media.url, media.thumbnailUrl, media.source, media.license, media.priority,
    ]),
  );
}

function buildRelationInserts({ exercises, mediaHosting }: CatalogSeedInput): RelationInsert[] {
  return [
    {
      table: "exercise_muscles", valueColumns: ["exercise_slug", "muscle_slug", "muscle_role"],
      insertColumns: "exercise_id, muscle_id, muscle_role", selectColumns: "e.id, m.id, v.muscle_role",
      extraJoin: "join public.muscles m on m.slug = v.muscle_slug", rows: buildMuscleRows(exercises),
    },
    {
      table: "exercise_equipment", valueColumns: ["exercise_slug", "equipment_slug"],
      insertColumns: "exercise_id, equipment_id", selectColumns: "e.id, q.id",
      extraJoin: "join public.equipment q on q.slug = v.equipment_slug",
      rows: exercises.flatMap((exercise) => exercise.equipment.map((equipment) => [exercise.slug, equipment])),
    },
    {
      table: "exercise_media", valueColumns: ["exercise_slug", "media_type", "url", "thumbnail_url", "source", "license", "priority"],
      insertColumns: "exercise_id, media_type, url, thumbnail_url, source, license, priority",
      selectColumns: "e.id, v.media_type, v.url, v.thumbnail_url, v.source, v.license, v.priority",
      rows: buildMediaRows(exercises, mediaHosting),
    },
    {
      table: "exercise_source_refs", valueColumns: ["exercise_slug", "source", "external_id"],
      insertColumns: "exercise_id, source, external_id", selectColumns: "e.id, v.source, v.external_id",
      rows: exercises.flatMap((exercise) => exercise.sourceRefs.map((ref) => [exercise.slug, ref.source, ref.externalId])),
    },
  ];
}

function buildRelationStatements(input: CatalogSeedInput): string[] {
  return [
    ...RELATION_TABLES.map((table) => `delete from public.${table};`),
    ...buildRelationInserts(input).map(buildRelationInsert).filter(Boolean),
  ];
}

/** Builds the idempotent SQL seed of the whole catalog (step 1.5). */
export function buildCatalogSeedSql(input: CatalogSeedInput): string {
  const toVocabularyRow = (entry: VocabularyEntry): SqlRow => [entry.slug, entry.namePt];
  const exerciseRows = input.exercises.map((exercise): SqlRow => [
    exercise.slug, exercise.namePt ?? exercise.nameEn, exercise.nameEn, exercise.difficulty, null,
  ]);
  const statements = [
    "begin;",
    buildUpsert("muscles", ["slug", "name_pt"], input.muscles.map(toVocabularyRow)),
    buildUpsert("equipment", ["slug", "name_pt"], input.equipment.map(toVocabularyRow)),
    buildUpsert("exercises", ["slug", "name_pt", "name_en", "difficulty", "instructions_pt"], exerciseRows),
    ...buildRelationStatements(input),
    "commit;",
  ];
  return `${HEADER}\n${statements.join("\n\n")}\n`;
}
